insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (6, 'draft', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あさごはんに <u>卵</u>を たべます。', '["たまご","にく","さかな","やさい"]'::jsonb, 0, '卵 dibaca “たまご” dan berarti telur.', 'Bab 6–10 · Mondai 1 No.1', 'kanji:卵'),
  (6, 'draft', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'はこの <u>上</u>に ねこが います。', '["うえ","した","なか","そと"]'::jsonb, 0, '上 dibaca “うえ” dan berarti atas.', 'Bab 6–10 · Mondai 1 No.2', 'kanji:上'),
  (6, 'draft', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ははに <u>手紙</u>を かきます。', '["てがみ","しゃしん","きっぷ","にもつ"]'::jsonb, 0, '手紙 dibaca “てがみ” dan berarti surat.', 'Bab 6–10 · Mondai 1 No.3', 'kanji:手紙'),
  (6, 'draft', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>父</u>は かいしゃいんです。', '["ちち","はは","あに","あね"]'::jsonb, 0, '父 dibaca “ちち” dan berarti ayah (dipakai untuk menyebut ayah sendiri).', 'Bab 6–10 · Mondai 1 No.4', 'kanji:父'),
  (6, 'draft', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは ちちに てがみを <u>送ります</u>。', '["おくります","かします","かります","おしえます"]'::jsonb, 0, '送ります dibaca “おくります” dan berarti mengirim.', 'Bab 6–10 · Mondai 1 No.5', 'kanji:送ります'),
  (6, 'draft', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>妹</u>は がくせいです。', '["いもうと","あね","むすめ","はは"]'::jsonb, 0, '妹 dibaca “いもうと” dan berarti adik perempuan.', 'Bab 6–10 · Mondai 1 No.6', 'kanji:妹'),
  (6, 'draft', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'このまちは とても <u>有名</u>です。', '["ゆうめい","げんき","べんり","しんせつ"]'::jsonb, 0, '有名 dibaca “ゆうめい” dan berarti terkenal.', 'Bab 6–10 · Mondai 1 No.7', 'kanji:有名'),
  (6, 'draft', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>新しい</u> れいぞうこを かいました。', '["あたらしい","ふるい","おおきい","ちいさい"]'::jsonb, 0, '新しい dibaca “あたらしい” dan berarti baru.', 'Bab 6–10 · Mondai 1 No.8', 'kanji:新しい'),
  (6, 'draft', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ふゆは とても <u>寒い</u>です。', '["さむい","あつい","つめたい","わるい"]'::jsonb, 0, '寒い dibaca “さむい” dan berarti dingin (cuaca/suhu).', 'Bab 6–10 · Mondai 1 No.9', 'kanji:寒い'),
  (6, 'draft', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは <u>音楽</u>が すきです。', '["おんがく","りょうり","りょこう","やきゅう"]'::jsonb, 0, '音楽 dibaca “おんがく” dan berarti musik.', 'Bab 6–10 · Mondai 1 No.10', 'kanji:音楽'),
  (6, 'draft', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいあさ おちゃを <u>のみます</u>。', '["飲みます","食べます","吸います","買います"]'::jsonb, 0, 'のみます ditulis 飲みます, berarti minum.', 'Bab 6–10 · Mondai 2 No.11', 'kanji:飲みます'),
  (6, 'draft', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'りょこうの <u>しゃしん</u>を とります。', '["写真","手紙","宿題","年賀状"]'::jsonb, 0, 'しゃしん ditulis 写真, berarti foto.', 'Bab 6–10 · Mondai 2 No.12', 'kanji:写真'),
  (6, 'draft', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>はは</u>は せんせいです。', '["母","父","姉","兄"]'::jsonb, 0, 'はは ditulis 母, berarti ibu (dipakai untuk menyebut ibu sendiri).', 'Bab 6–10 · Mondai 2 No.13', 'kanji:母'),
  (6, 'draft', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'としょかんで ほんを <u>かります</u>。', '["借ります","貸します","教えます","習います"]'::jsonb, 0, 'かります ditulis 借ります, berarti meminjam.', 'Bab 6–10 · Mondai 2 No.14', 'kanji:借ります'),
  (6, 'draft', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'このでんしゃは とても <u>べんり</u>です。', '["便利","有名","元気","大きい"]'::jsonb, 0, 'べんり ditulis 便利, berarti praktis.', 'Bab 6–10 · Mondai 2 No.15', 'kanji:便利'),
  (6, 'draft', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この <u>りょうり</u>が すきです。', '["料理","音楽","野球","旅行"]'::jsonb, 0, 'りょうり ditulis 料理, berarti masakan.', 'Bab 6–10 · Mondai 2 No.16', 'kanji:料理'),
  (6, 'draft', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>まど</u>は そこです。', '["窓","箱","棚","木"]'::jsonb, 0, 'まど ditulis 窓, berarti jendela.', 'Bab 6–10 · Mondai 2 No.17', 'kanji:窓'),
  (6, 'draft', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こうえんの <u>ちかく</u>に みせが あります。', '["近く","隣","間","中"]'::jsonb, 0, 'ちかく ditulis 近く, berarti dekat.', 'Bab 6–10 · Mondai 2 No.18', 'kanji:近く'),
  (6, 'draft', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この <u>かんじ</u>が わかりません。', '["漢字","音楽","料理","写真"]'::jsonb, 0, 'かんじ ditulis 漢字, berarti aksara kanji.', 'Bab 6–10 · Mondai 2 No.19', 'kanji:漢字'),
  (6, 'draft', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>いぬ</u>が こうえんに います。', '["犬","猫","窓","写真"]'::jsonb, 0, 'いぬ ditulis 犬, berarti anjing.', 'Bab 6–10 · Mondai 2 No.20', 'kanji:犬'),
  (6, 'draft', 20, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>のみます。</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>ジュース</span></div><small>Petunjuk arti: “Minum jus.”</small>', '["③→②→①","①→③→②","②→①→③","②→③→①"]'::jsonb, 0, 'Urutan yang benar: ③ジュース→②を→①のみます。 を menandai objek dari kata kerja transitif seperti のみます (Pel.6).', 'Bab 6–10 · Mondai 3 No.21', 'materi:book1:5:0'),
  (6, 'draft', 21, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>しんぶんをかいます。</span><span class="arrange-chip"><b>②</b>で</span><span class="arrange-chip"><b>③</b>えき</span></div><small>Petunjuk arti: “Membeli surat kabar di stasiun.”</small>', '["③→②→①","②→③→①","②→①→③","③→①→②"]'::jsonb, 0, 'Urutan yang benar: ③えき→②で→①しんぶんをかいます。 で menandai tempat berlangsungnya suatu kegiatan (Pel.6).', 'Bab 6–10 · Mondai 3 No.22', 'materi:book1:5:0'),
  (6, 'draft', 22, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はなをあげました。</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>きむらさん</span></div><small>Petunjuk arti: “Saya memberikan bunga kepada Sdr. Kimura.”</small>', '["③→②→①","②→③→①","②→①→③","③→①→②"]'::jsonb, 0, 'Urutan yang benar: ③きむらさん→②に→①はなをあげました。 に menandai penerima dalam pola memberi（あげます）(Pel.7).', 'Bab 6–10 · Mondai 3 No.23', 'materi:book1:6:0'),
  (6, 'draft', 23, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はし</span><span class="arrange-chip"><b>②</b>たべます。</span><span class="arrange-chip"><b>③</b>で</span></div><small>Petunjuk arti: “Makan dengan sumpit.”</small>', '["①→③→②","②→①→③","③→②→①","③→①→②"]'::jsonb, 0, 'Urutan yang benar: ①はし→③で→②たべます。 で menandai alat atau sarana yang dipakai (Pel.7).', 'Bab 6–10 · Mondai 3 No.24', 'materi:book1:6:0'),
  (6, 'draft', 24, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>おかねをかりました。</span><span class="arrange-chip"><b>②</b>ぎんこう</span><span class="arrange-chip"><b>③</b>から</span></div><small>Petunjuk arti: “Saya meminjam uang dari bank.”</small>', '["②→③→①","②→①→③","①→②→③","③→②→①"]'::jsonb, 0, 'Urutan yang benar: ②ぎんこう→③から→①おかねをかりました。 から menandai sumber, dipakai sebagai pengganti に kalau lawannya organisasi seperti bank (Pel.7).', 'Bab 6–10 · Mondai 3 No.25', 'materi:book1:6:0'),
  (6, 'draft', 25, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>イタリアりょうり</span><span class="arrange-chip"><b>③</b>わたしは</span><span class="arrange-chip"><b>④</b>すきです。</span></div><small>Petunjuk arti: “Saya suka masakan Italia.”</small>', '["③→②→①→④","④→①→③→②","①→③→④→②","②→①→④→③"]'::jsonb, 0, 'Urutan yang benar: ③わたしは→②イタリアりょうり→①が→④すきです。 が menandai objek dari kata seperti すき, わかります, あります (Pel.9).', 'Bab 6–10 · Mondai 3 No.26', 'materi:book1:8:0'),
  (6, 'draft', 26, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ありません</span><span class="arrange-chip"><b>②</b>から</span><span class="arrange-chip"><b>③</b>しんぶんをよみません。</span><span class="arrange-chip"><b>④</b>じかんが</span></div><small>Petunjuk arti: “Karena tidak ada waktu, saya tidak membaca koran.”</small>', '["④→①→②→③","④→③→①→②","③→④→②→①","①→②→③→④"]'::jsonb, 0, 'Urutan yang benar: ④じかんが→①ありません→②から→③しんぶんをよみません。 から menandai alasan, diletakkan setelah klausa alasannya (Pel.9).', 'Bab 6–10 · Mondai 3 No.27', 'materi:book1:8:0'),
  (6, 'draft', 27, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>てがみ</span><span class="arrange-chip"><b>②</b>や</span><span class="arrange-chip"><b>③</b>しゃしんがあります。</span><span class="arrange-chip"><b>④</b>はこのなかに</span></div><small>Petunjuk arti: “Di dalam kotak ada surat dan foto.”</small>', '["④→①→②→③","④→②→①→③","②→③→①→④","②→①→③→④"]'::jsonb, 0, 'Urutan yang benar: ④はこのなかに→①てがみ→②や→③しゃしんがあります。 や dipakai menyebutkan beberapa contoh benda secara tidak lengkap, berbeda dari と yang menyebutkan semuanya (Pel.10).', 'Bab 6–10 · Mondai 3 No.28', 'materi:book1:9:0'),
  (6, 'draft', 28, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>つくえがあります。</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>わたしのへや</span></div><small>Petunjuk arti: “Di kamar saya ada meja.”</small>', '["③→②→①","①→③→②","①→②→③","②→③→①"]'::jsonb, 0, 'Urutan yang benar: ③わたしのへや→②に→①つくえがあります。 に menandai tempat keberadaan benda/orang bersama あります／います (Pel.10).', 'Bab 6–10 · Mondai 3 No.29', 'materi:book1:9:0'),
  (6, 'draft', 29, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>の</span><span class="arrange-chip"><b>②</b>つくえ</span><span class="arrange-chip"><b>③</b>うえにしゃしんがあります。</span></div><small>Petunjuk arti: “Di atas meja ada foto.”</small>', '["②→①→③","③→②→①","①→②→③","③→①→②"]'::jsonb, 0, 'Urutan yang benar: ②つくえ→①の→③うえにしゃしんがあります。 の menghubungkan kata benda dengan kata posisi seperti うえ、した、まえ (Pel.10).', 'Bab 6–10 · Mondai 3 No.30', 'materi:book1:9:0'),
  (6, 'draft', 30, 'Susunan Kalimat', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>きょうとへ</span><span class="arrange-chip"><b>②</b>いっしょに</span><span class="arrange-chip"><b>③</b>いきませんか。</span></div><small>Petunjuk arti: “Bagaimana kalau kita pergi ke Kyoto bersama-sama?”</small>', '["②→①→③","③→①→②","①→②→③","①→③→②"]'::jsonb, 0, 'Urutan yang benar: ②いっしょに→①きょうとへ→③いきませんか。 Kata Kerjaませんか dipakai untuk mengajak lawan bicara secara sopan (Pel.6).', 'Bab 6–10 · Mondai 4 No.31', 'materi:book1:5:0'),
  (6, 'draft', 31, 'Susunan Kalimat', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>えいごをおしえます。</span><span class="arrange-chip"><b>②</b>やまださんに</span><span class="arrange-chip"><b>③</b>わたしは</span></div><small>Petunjuk arti: “Saya mengajar bahasa Inggris kepada Sdr. Yamada.”</small>', '["③→②→①","③→①→②","①→②→③","②→①→③"]'::jsonb, 0, 'Urutan yang benar: ③わたしは→②やまださんに→①えいごをおしえます。 Kata Kerja おしえます memerlukan penerima yang ditandai に sebelum objeknya (Pel.7).', 'Bab 6–10 · Mondai 4 No.32', 'materi:book1:6:0'),
  (6, 'draft', 32, 'Susunan Kalimat', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>やまです。</span><span class="arrange-chip"><b>②</b>たかい</span><span class="arrange-chip"><b>③</b>富士山は</span></div><small>Petunjuk arti: “Gunung Fuji adalah gunung yang tinggi.”</small>', '["③→②→①","③→①→②","②→③→①","①→②→③"]'::jsonb, 0, 'Urutan yang benar: ③富士山は→②たかい→①やまです。 Kata Sifat い menerangkan Kata Benda dengan diletakkan langsung di depannya (Pel.8).', 'Bab 6–10 · Mondai 4 No.33', 'materi:book1:7:0'),
  (6, 'draft', 33, 'Susunan Kalimat', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>よく</span><span class="arrange-chip"><b>②</b>わかります。</span><span class="arrange-chip"><b>③</b>えいごが</span></div><small>Petunjuk arti: “Saya mengerti bahasa Inggris dengan baik.”</small>', '["③→①→②","①→③→②","②→③→①","②→①→③"]'::jsonb, 0, 'Urutan yang benar: ③えいごが→①よく→②わかります。 Kata keterangan tingkat seperti よく diletakkan tepat di depan kata kerja yang diterangkannya (Pel.9).', 'Bab 6–10 · Mondai 4 No.34', 'materi:book1:8:0'),
  (6, 'draft', 34, 'Susunan Kalimat', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はなやとスーパーの</span><span class="arrange-chip"><b>②</b>あります。</span><span class="arrange-chip"><b>③</b>ほんやは</span><span class="arrange-chip"><b>④</b>あいだに</span></div><small>Petunjuk arti: “Toko buku ada di antara toko bunga dan pasar swalayan.”</small>', '["③→①→④→②","③→①→②→④","②→①→③→④","①→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ③ほんやは→①はなやとスーパーの→④あいだに→②あります。 あいだ menunjukkan posisi “di antara” dua Kata Benda (Pel.10).', 'Bab 6–10 · Mondai 4 No.35', 'materi:book1:9:0'),
  (6, 'draft', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きょうは　天気が　いいです。公園で　サッカーを　しませんか。……ええ、しましょう。<br><small>何を　しますか。</small>', '["サッカー","やきゅう","すいえい","りょこう"]'::jsonb, 0, 'Ajakan「公園でサッカーをしませんか」dijawab dengan「ええ、しましょう」, artinya mereka sepakat bermain sepak bola. Pola Kata Kerjaませんか untuk mengajak dan ましょう untuk menyetujui (Pel.6).', 'Bab 6–10 · Soal Cerita No.36', 'materi:book1:5:0'),
  (6, 'draft', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きのう、たんじょうびでした。山田さんに　花を　もらいました。わたしは　木村さんに　手紙を　あげました。<br><small>だれが　わたしに　花を　あげましたか。</small>', '["山田さん","木村さん","先生","家族"]'::jsonb, 0, 'Kalimat「山田さんに花をもらいました」berarti “menerima bunga DARI Sdr. Yamada”, jadi Sdr. Yamada-lah yang memberi bunga (Pel.7).', 'Bab 6–10 · Soal Cerita No.37', 'materi:book1:6:0'),
  (6, 'draft', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしの　まちは　しずかです。でも、あまり　べんりじゃ　ありません。みせは　とても　ちいさいです。<br><small>わたしの　まちは　どうですか。</small>', '["にぎやかで　べんりです。","しずかですが、あまり　べんりじゃ　ありません。","うるさくて　きたないです。","ちいさくて　たかいです。"]'::jsonb, 1, 'Cerita menyebutkan “sunyi” (しずかです) TETAPI “kurang praktis” (あまりべんりじゃありません) — pola kontras ～が、～ menghubungkan dua sifat yang berlawanan (Pel.8).', 'Bab 6–10 · Soal Cerita No.38', 'materi:book1:7:0'),
  (6, 'draft', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは　音楽が　好きです。でも、時間が　ぜんぜん　ありませんから、うたを　あまり　ききません。<br><small>どうして　うたを　あまり　ききませんか。</small>', '["音楽が　きらいですから","時間が　ぜんぜん　ありませんから","うたが　きらいですから","うるさいですから"]'::jsonb, 1, 'Kalimat terakhir menyebutkan alasannya: 「時間がぜんぜんありませんから」(karena sama sekali tidak ada waktu), memakai pola ～から untuk menyatakan alasan (Pel.9).', 'Bab 6–10 · Soal Cerita No.39', 'materi:book1:8:0'),
  (6, 'draft', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしの　へやに　つくえが　あります。つくえの　うえに　写真が　あります。犬は　つくえの　したに　います。<br><small>犬は　どこに　いますか。</small>', '["つくえの　うえ","つくえの　した","つくえの　なか","つくえの　まえ"]'::jsonb, 1, 'Kalimat terakhir menyebutkan「犬はつくえのしたにいます」(anjing ada di bawah meja), memakai pola Kata Benda1の Kata Benda2（posisi）untuk menyatakan posisi relatif (Pel.10).', 'Bab 6–10 · Soal Cerita No.40', 'materi:book1:9:0');
insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (6, 'published', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'あさごはんに <u>卵</u>を たべます。', '["たまご","にく","さかな","やさい"]'::jsonb, 0, '卵 dibaca “たまご” dan berarti telur.', 'Bab 6–10 · Mondai 1 No.1', 'kanji:卵'),
  (6, 'published', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'はこの <u>上</u>に ねこが います。', '["うえ","した","なか","そと"]'::jsonb, 0, '上 dibaca “うえ” dan berarti atas.', 'Bab 6–10 · Mondai 1 No.2', 'kanji:上'),
  (6, 'published', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ははに <u>手紙</u>を かきます。', '["てがみ","しゃしん","きっぷ","にもつ"]'::jsonb, 0, '手紙 dibaca “てがみ” dan berarti surat.', 'Bab 6–10 · Mondai 1 No.3', 'kanji:手紙'),
  (6, 'published', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>父</u>は かいしゃいんです。', '["ちち","はは","あに","あね"]'::jsonb, 0, '父 dibaca “ちち” dan berarti ayah (dipakai untuk menyebut ayah sendiri).', 'Bab 6–10 · Mondai 1 No.4', 'kanji:父'),
  (6, 'published', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは ちちに てがみを <u>送ります</u>。', '["おくります","かします","かります","おしえます"]'::jsonb, 0, '送ります dibaca “おくります” dan berarti mengirim.', 'Bab 6–10 · Mondai 1 No.5', 'kanji:送ります'),
  (6, 'published', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>妹</u>は がくせいです。', '["いもうと","あね","むすめ","はは"]'::jsonb, 0, '妹 dibaca “いもうと” dan berarti adik perempuan.', 'Bab 6–10 · Mondai 1 No.6', 'kanji:妹'),
  (6, 'published', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'このまちは とても <u>有名</u>です。', '["ゆうめい","げんき","べんり","しんせつ"]'::jsonb, 0, '有名 dibaca “ゆうめい” dan berarti terkenal.', 'Bab 6–10 · Mondai 1 No.7', 'kanji:有名'),
  (6, 'published', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>新しい</u> れいぞうこを かいました。', '["あたらしい","ふるい","おおきい","ちいさい"]'::jsonb, 0, '新しい dibaca “あたらしい” dan berarti baru.', 'Bab 6–10 · Mondai 1 No.8', 'kanji:新しい'),
  (6, 'published', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ふゆは とても <u>寒い</u>です。', '["さむい","あつい","つめたい","わるい"]'::jsonb, 0, '寒い dibaca “さむい” dan berarti dingin (cuaca/suhu).', 'Bab 6–10 · Mondai 1 No.9', 'kanji:寒い'),
  (6, 'published', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'わたしは <u>音楽</u>が すきです。', '["おんがく","りょうり","りょこう","やきゅう"]'::jsonb, 0, '音楽 dibaca “おんがく” dan berarti musik.', 'Bab 6–10 · Mondai 1 No.10', 'kanji:音楽'),
  (6, 'published', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まいあさ おちゃを <u>のみます</u>。', '["飲みます","食べます","吸います","買います"]'::jsonb, 0, 'のみます ditulis 飲みます, berarti minum.', 'Bab 6–10 · Mondai 2 No.11', 'kanji:飲みます'),
  (6, 'published', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'りょこうの <u>しゃしん</u>を とります。', '["写真","手紙","宿題","年賀状"]'::jsonb, 0, 'しゃしん ditulis 写真, berarti foto.', 'Bab 6–10 · Mondai 2 No.12', 'kanji:写真'),
  (6, 'published', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>はは</u>は せんせいです。', '["母","父","姉","兄"]'::jsonb, 0, 'はは ditulis 母, berarti ibu (dipakai untuk menyebut ibu sendiri).', 'Bab 6–10 · Mondai 2 No.13', 'kanji:母'),
  (6, 'published', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'としょかんで ほんを <u>かります</u>。', '["借ります","貸します","教えます","習います"]'::jsonb, 0, 'かります ditulis 借ります, berarti meminjam.', 'Bab 6–10 · Mondai 2 No.14', 'kanji:借ります'),
  (6, 'published', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'このでんしゃは とても <u>べんり</u>です。', '["便利","有名","元気","大きい"]'::jsonb, 0, 'べんり ditulis 便利, berarti praktis.', 'Bab 6–10 · Mondai 2 No.15', 'kanji:便利'),
  (6, 'published', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この <u>りょうり</u>が すきです。', '["料理","音楽","野球","旅行"]'::jsonb, 0, 'りょうり ditulis 料理, berarti masakan.', 'Bab 6–10 · Mondai 2 No.16', 'kanji:料理'),
  (6, 'published', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>まど</u>は そこです。', '["窓","箱","棚","木"]'::jsonb, 0, 'まど ditulis 窓, berarti jendela.', 'Bab 6–10 · Mondai 2 No.17', 'kanji:窓'),
  (6, 'published', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こうえんの <u>ちかく</u>に みせが あります。', '["近く","隣","間","中"]'::jsonb, 0, 'ちかく ditulis 近く, berarti dekat.', 'Bab 6–10 · Mondai 2 No.18', 'kanji:近く'),
  (6, 'published', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この <u>かんじ</u>が わかりません。', '["漢字","音楽","料理","写真"]'::jsonb, 0, 'かんじ ditulis 漢字, berarti aksara kanji.', 'Bab 6–10 · Mondai 2 No.19', 'kanji:漢字'),
  (6, 'published', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>いぬ</u>が こうえんに います。', '["犬","猫","窓","写真"]'::jsonb, 0, 'いぬ ditulis 犬, berarti anjing.', 'Bab 6–10 · Mondai 2 No.20', 'kanji:犬'),
  (6, 'published', 20, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>のみます。</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>ジュース</span></div><small>Petunjuk arti: “Minum jus.”</small>', '["③→②→①","①→③→②","②→①→③","②→③→①"]'::jsonb, 0, 'Urutan yang benar: ③ジュース→②を→①のみます。 を menandai objek dari kata kerja transitif seperti のみます (Pel.6).', 'Bab 6–10 · Mondai 3 No.21', 'materi:book1:5:0'),
  (6, 'published', 21, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>しんぶんをかいます。</span><span class="arrange-chip"><b>②</b>で</span><span class="arrange-chip"><b>③</b>えき</span></div><small>Petunjuk arti: “Membeli surat kabar di stasiun.”</small>', '["③→②→①","②→③→①","②→①→③","③→①→②"]'::jsonb, 0, 'Urutan yang benar: ③えき→②で→①しんぶんをかいます。 で menandai tempat berlangsungnya suatu kegiatan (Pel.6).', 'Bab 6–10 · Mondai 3 No.22', 'materi:book1:5:0'),
  (6, 'published', 22, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はなをあげました。</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>きむらさん</span></div><small>Petunjuk arti: “Saya memberikan bunga kepada Sdr. Kimura.”</small>', '["③→②→①","②→③→①","②→①→③","③→①→②"]'::jsonb, 0, 'Urutan yang benar: ③きむらさん→②に→①はなをあげました。 に menandai penerima dalam pola memberi（あげます）(Pel.7).', 'Bab 6–10 · Mondai 3 No.23', 'materi:book1:6:0'),
  (6, 'published', 23, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はし</span><span class="arrange-chip"><b>②</b>たべます。</span><span class="arrange-chip"><b>③</b>で</span></div><small>Petunjuk arti: “Makan dengan sumpit.”</small>', '["①→③→②","②→①→③","③→②→①","③→①→②"]'::jsonb, 0, 'Urutan yang benar: ①はし→③で→②たべます。 で menandai alat atau sarana yang dipakai (Pel.7).', 'Bab 6–10 · Mondai 3 No.24', 'materi:book1:6:0'),
  (6, 'published', 24, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>おかねをかりました。</span><span class="arrange-chip"><b>②</b>ぎんこう</span><span class="arrange-chip"><b>③</b>から</span></div><small>Petunjuk arti: “Saya meminjam uang dari bank.”</small>', '["②→③→①","②→①→③","①→②→③","③→②→①"]'::jsonb, 0, 'Urutan yang benar: ②ぎんこう→③から→①おかねをかりました。 から menandai sumber, dipakai sebagai pengganti に kalau lawannya organisasi seperti bank (Pel.7).', 'Bab 6–10 · Mondai 3 No.25', 'materi:book1:6:0'),
  (6, 'published', 25, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>イタリアりょうり</span><span class="arrange-chip"><b>③</b>わたしは</span><span class="arrange-chip"><b>④</b>すきです。</span></div><small>Petunjuk arti: “Saya suka masakan Italia.”</small>', '["③→②→①→④","④→①→③→②","①→③→④→②","②→①→④→③"]'::jsonb, 0, 'Urutan yang benar: ③わたしは→②イタリアりょうり→①が→④すきです。 が menandai objek dari kata seperti すき, わかります, あります (Pel.9).', 'Bab 6–10 · Mondai 3 No.26', 'materi:book1:8:0'),
  (6, 'published', 26, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ありません</span><span class="arrange-chip"><b>②</b>から</span><span class="arrange-chip"><b>③</b>しんぶんをよみません。</span><span class="arrange-chip"><b>④</b>じかんが</span></div><small>Petunjuk arti: “Karena tidak ada waktu, saya tidak membaca koran.”</small>', '["④→①→②→③","④→③→①→②","③→④→②→①","①→②→③→④"]'::jsonb, 0, 'Urutan yang benar: ④じかんが→①ありません→②から→③しんぶんをよみません。 から menandai alasan, diletakkan setelah klausa alasannya (Pel.9).', 'Bab 6–10 · Mondai 3 No.27', 'materi:book1:8:0'),
  (6, 'published', 27, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>てがみ</span><span class="arrange-chip"><b>②</b>や</span><span class="arrange-chip"><b>③</b>しゃしんがあります。</span><span class="arrange-chip"><b>④</b>はこのなかに</span></div><small>Petunjuk arti: “Di dalam kotak ada surat dan foto.”</small>', '["④→①→②→③","④→②→①→③","②→③→①→④","②→①→③→④"]'::jsonb, 0, 'Urutan yang benar: ④はこのなかに→①てがみ→②や→③しゃしんがあります。 や dipakai menyebutkan beberapa contoh benda secara tidak lengkap, berbeda dari と yang menyebutkan semuanya (Pel.10).', 'Bab 6–10 · Mondai 3 No.28', 'materi:book1:9:0'),
  (6, 'published', 28, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>つくえがあります。</span><span class="arrange-chip"><b>②</b>に</span><span class="arrange-chip"><b>③</b>わたしのへや</span></div><small>Petunjuk arti: “Di kamar saya ada meja.”</small>', '["③→②→①","①→③→②","①→②→③","②→③→①"]'::jsonb, 0, 'Urutan yang benar: ③わたしのへや→②に→①つくえがあります。 に menandai tempat keberadaan benda/orang bersama あります／います (Pel.10).', 'Bab 6–10 · Mondai 3 No.29', 'materi:book1:9:0'),
  (6, 'published', 29, 'Partikel', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>の</span><span class="arrange-chip"><b>②</b>つくえ</span><span class="arrange-chip"><b>③</b>うえにしゃしんがあります。</span></div><small>Petunjuk arti: “Di atas meja ada foto.”</small>', '["②→①→③","③→②→①","①→②→③","③→①→②"]'::jsonb, 0, 'Urutan yang benar: ②つくえ→①の→③うえにしゃしんがあります。 の menghubungkan kata benda dengan kata posisi seperti うえ、した、まえ (Pel.10).', 'Bab 6–10 · Mondai 3 No.30', 'materi:book1:9:0'),
  (6, 'published', 30, 'Susunan Kalimat', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>きょうとへ</span><span class="arrange-chip"><b>②</b>いっしょに</span><span class="arrange-chip"><b>③</b>いきませんか。</span></div><small>Petunjuk arti: “Bagaimana kalau kita pergi ke Kyoto bersama-sama?”</small>', '["②→①→③","③→①→②","①→②→③","①→③→②"]'::jsonb, 0, 'Urutan yang benar: ②いっしょに→①きょうとへ→③いきませんか。 Kata Kerjaませんか dipakai untuk mengajak lawan bicara secara sopan (Pel.6).', 'Bab 6–10 · Mondai 4 No.31', 'materi:book1:5:0'),
  (6, 'published', 31, 'Susunan Kalimat', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>えいごをおしえます。</span><span class="arrange-chip"><b>②</b>やまださんに</span><span class="arrange-chip"><b>③</b>わたしは</span></div><small>Petunjuk arti: “Saya mengajar bahasa Inggris kepada Sdr. Yamada.”</small>', '["③→②→①","③→①→②","①→②→③","②→①→③"]'::jsonb, 0, 'Urutan yang benar: ③わたしは→②やまださんに→①えいごをおしえます。 Kata Kerja おしえます memerlukan penerima yang ditandai に sebelum objeknya (Pel.7).', 'Bab 6–10 · Mondai 4 No.32', 'materi:book1:6:0'),
  (6, 'published', 32, 'Susunan Kalimat', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>やまです。</span><span class="arrange-chip"><b>②</b>たかい</span><span class="arrange-chip"><b>③</b>富士山は</span></div><small>Petunjuk arti: “Gunung Fuji adalah gunung yang tinggi.”</small>', '["③→②→①","③→①→②","②→③→①","①→②→③"]'::jsonb, 0, 'Urutan yang benar: ③富士山は→②たかい→①やまです。 Kata Sifat い menerangkan Kata Benda dengan diletakkan langsung di depannya (Pel.8).', 'Bab 6–10 · Mondai 4 No.33', 'materi:book1:7:0'),
  (6, 'published', 33, 'Susunan Kalimat', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>よく</span><span class="arrange-chip"><b>②</b>わかります。</span><span class="arrange-chip"><b>③</b>えいごが</span></div><small>Petunjuk arti: “Saya mengerti bahasa Inggris dengan baik.”</small>', '["③→①→②","①→③→②","②→③→①","②→①→③"]'::jsonb, 0, 'Urutan yang benar: ③えいごが→①よく→②わかります。 Kata keterangan tingkat seperti よく diletakkan tepat di depan kata kerja yang diterangkannya (Pel.9).', 'Bab 6–10 · Mondai 4 No.34', 'materi:book1:8:0'),
  (6, 'published', 34, 'Susunan Kalimat', 'Kata-kata di bawah sudah diberi nomor acak. Pilih urutan nomor yang membentuk kalimat yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>はなやとスーパーの</span><span class="arrange-chip"><b>②</b>あります。</span><span class="arrange-chip"><b>③</b>ほんやは</span><span class="arrange-chip"><b>④</b>あいだに</span></div><small>Petunjuk arti: “Toko buku ada di antara toko bunga dan pasar swalayan.”</small>', '["③→①→④→②","③→①→②→④","②→①→③→④","①→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ③ほんやは→①はなやとスーパーの→④あいだに→②あります。 あいだ menunjukkan posisi “di antara” dua Kata Benda (Pel.10).', 'Bab 6–10 · Mondai 4 No.35', 'materi:book1:9:0'),
  (6, 'published', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きょうは　天気が　いいです。公園で　サッカーを　しませんか。……ええ、しましょう。<br><small>何を　しますか。</small>', '["サッカー","やきゅう","すいえい","りょこう"]'::jsonb, 0, 'Ajakan「公園でサッカーをしませんか」dijawab dengan「ええ、しましょう」, artinya mereka sepakat bermain sepak bola. Pola Kata Kerjaませんか untuk mengajak dan ましょう untuk menyetujui (Pel.6).', 'Bab 6–10 · Soal Cerita No.36', 'materi:book1:5:0'),
  (6, 'published', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きのう、たんじょうびでした。山田さんに　花を　もらいました。わたしは　木村さんに　手紙を　あげました。<br><small>だれが　わたしに　花を　あげましたか。</small>', '["山田さん","木村さん","先生","家族"]'::jsonb, 0, 'Kalimat「山田さんに花をもらいました」berarti “menerima bunga DARI Sdr. Yamada”, jadi Sdr. Yamada-lah yang memberi bunga (Pel.7).', 'Bab 6–10 · Soal Cerita No.37', 'materi:book1:6:0'),
  (6, 'published', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしの　まちは　しずかです。でも、あまり　べんりじゃ　ありません。みせは　とても　ちいさいです。<br><small>わたしの　まちは　どうですか。</small>', '["にぎやかで　べんりです。","しずかですが、あまり　べんりじゃ　ありません。","うるさくて　きたないです。","ちいさくて　たかいです。"]'::jsonb, 1, 'Cerita menyebutkan “sunyi” (しずかです) TETAPI “kurang praktis” (あまりべんりじゃありません) — pola kontras ～が、～ menghubungkan dua sifat yang berlawanan (Pel.8).', 'Bab 6–10 · Soal Cerita No.38', 'materi:book1:7:0'),
  (6, 'published', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは　音楽が　好きです。でも、時間が　ぜんぜん　ありませんから、うたを　あまり　ききません。<br><small>どうして　うたを　あまり　ききませんか。</small>', '["音楽が　きらいですから","時間が　ぜんぜん　ありませんから","うたが　きらいですから","うるさいですから"]'::jsonb, 1, 'Kalimat terakhir menyebutkan alasannya: 「時間がぜんぜんありませんから」(karena sama sekali tidak ada waktu), memakai pola ～から untuk menyatakan alasan (Pel.9).', 'Bab 6–10 · Soal Cerita No.39', 'materi:book1:8:0'),
  (6, 'published', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしの　へやに　つくえが　あります。つくえの　うえに　写真が　あります。犬は　つくえの　したに　います。<br><small>犬は　どこに　いますか。</small>', '["つくえの　うえ","つくえの　した","つくえの　なか","つくえの　まえ"]'::jsonb, 1, 'Kalimat terakhir menyebutkan「犬はつくえのしたにいます」(anjing ada di bawah meja), memakai pola Kata Benda1の Kata Benda2（posisi）untuk menyatakan posisi relatif (Pel.10).', 'Bab 6–10 · Soal Cerita No.40', 'materi:book1:9:0');
